-- 001_init.sql — commit/snapshot bookkeeping for codeindex.
-- Forward-only. Do not edit this file after it has been applied; create a new
-- migration script instead. The runner verifies the checksum on every run.
--
-- Chunk storage is no longer owned here: @agent-local/vectorstore creates and
-- owns its own `vector_records` table (PgVectorStore.ensureSchema), keyed by
-- namespace = commit_sha. This migration manages only the `commits` table.

CREATE TABLE IF NOT EXISTS commits (
    commit_sha    TEXT PRIMARY KEY,
    branch        TEXT NOT NULL,
    indexed_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    embed_model   TEXT NOT NULL,
    embed_dim     INTEGER NOT NULL,
    file_count    INTEGER NOT NULL,
    chunk_count   INTEGER NOT NULL
);

CREATE INDEX IF NOT EXISTS commits_branch_idx ON commits (branch, indexed_at DESC);
